# -*- coding: utf-8 -*-
import json
F = json.load(open("pedidos/_todos.json"))
for k in ("p001_a", "p001_b", "p001_c"):
    F.pop(k, None)
have = {"p027", "p076", "p106", "p118", "p001"}
ids = []
for x in json.load(open("planos.json")):
    i = x["id"]
    if i in F and i not in have and not i.startswith("s0"):
        ids.append(i)
print(len(ids), ids)
lotes = [ids[:40], ids[40:80]]
for n, L in enumerate(lotes, 2):
    json.dump([F[i] for i in L], open("pedidos/lote0%d.json" % n, "w"), ensure_ascii=False, indent=1)
    print("lote0%d" % n, len(L))

